"""License-clear synthetic fixture used only to exercise the harness end to end."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

FIXTURE_NAME = "lantern_harbor.en.md"
LICENSE = "CC0-1.0"
PROVENANCE = (
    "Synthetic English text generated by tools/eval/wenyi_eval/fixture.py for harness "
    "validation; contains no third-party text."
)

CHAPTER_TITLES = (
    "Chapter 1: The Harbor",
    "Chapter 2: The Map",
    "Chapter 3: The Keeper",
    "Chapter 4: The Gull",
    "Chapter 5: The Fog",
    "Chapter 6: The Spring",
    "Chapter 7: The Gate",
    "Chapter 8: The Bells",
    "Chapter 9: The Tide",
    "Chapter 10: Morning",
)

TEMPLATES = (
    "Mira carried the old map to the pier.",
    "The lantern glowed over the quiet harbor.",
    "Every evening the keeper lit the lamp.",
    "A gull circled twice, then vanished.",
    '"The tide is turning," Mira said quietly.',
    '"We should leave before the fog arrives," said the keeper.',
    "Mira wondered whether the old path still led to the spring.",
    "She remembered the winter when the harbor froze.",
    "Red ink marked the hidden spring on the map.",
    "The eastern gate opened at dawn.",
    "Bells rang across the water.",
    "Lantern light on water; a map folded in her hand; the keeper waits for morning.",
)

PARAGRAPHS_PER_CHAPTER = 24


def chapter_paragraphs(chapter_index: int) -> list[str]:
    return [
        TEMPLATES[(chapter_index * 3 + offset) % len(TEMPLATES)]
        for offset in range(PARAGRAPHS_PER_CHAPTER)
    ]


def render_markdown() -> str:
    blocks = ["# The Lantern Harbor"]
    for index, title in enumerate(CHAPTER_TITLES):
        blocks.append(f"# {title}")
        blocks.extend(chapter_paragraphs(index))
    return "\n\n".join(blocks) + "\n"


def fixture_metadata() -> dict[str, Any]:
    return {
        "title": "The Lantern Harbor",
        "author": "Wenyi evaluation harness contributors",
        "license": LICENSE,
        "provenance": PROVENANCE,
        "synthetic": True,
        "source_language": "en",
        "target_language": "zh",
        "created": "2026-11-16",
        "chapters": len(CHAPTER_TITLES),
        "paragraphs": len(CHAPTER_TITLES) * PARAGRAPHS_PER_CHAPTER,
    }


def write_fixture(directory: str | Path) -> tuple[Path, Path]:
    target = Path(directory)
    target.mkdir(parents=True, exist_ok=True)
    source = target / FIXTURE_NAME
    source.write_text(render_markdown(), encoding="utf-8", newline="\n")
    metadata = target / "fixture.json"
    metadata.write_text(
        json.dumps(fixture_metadata(), ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return source, metadata
